#include "ge_glu_v2_kernel.h"
extern "C" __global__ __aicore__ void ge_glu_v2_custom_fp32(GM_ADDR x, GM_ADDR y, GM_ADDR t) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    GeGluV2Kernel<float> k; k.Init(x, y, t, &p); k.Process();
}
extern "C" void ge_glu_v2_do_fp32(uint32_t d, void* s, uint8_t* x, uint8_t* y, uint8_t* t) {
    ge_glu_v2_custom_fp32<<<d, nullptr, s>>>(x, y, t);
}

